"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["4121"],{2063(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>i,contentTitle:()=>s,toc:()=>c,assets:()=>d});var n=JSON.parse('{"id":"reference/configure/howtos/retrieveDataInADataset","title":"How to retrieve device data in a dataset?","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/configure/howtos/retrieveDataInADataset.md","sourceDirName":"reference/configure/howtos","slug":"/reference/configure/howtos/retrieveDataInADataset","permalink":"/personal-av-docs/docs/reference/configure/howtos/retrieveDataInADataset","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/configure/howtos/retrieveDataInADataset.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to retrieve device data in a dataset?","sidebar_label":"How to retrieve device data in a dataset","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/configure/howtos/retrieveDataInADataset","format":"md"}}'),o=a(4848),r=a(8453);let i={title:"How to retrieve device data in a dataset?",sidebar_label:"How to retrieve device data in a dataset",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/configure/howtos/retrieveDataInADataset",format:"md"},s,d={},c=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/configure/howtos/retrieveDataInADataset",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"How to retrieve device data in a dataset?\nHow to configure an SMS account?\nHow to find a system\nVideo Series\nReferences\nDevice Management Activities\nAdditional Information on Subscription Management\nDashboard\nInventory\nAdministration\nRegister\nMonitor\nConfigure\nReporting\nDevelop\nAirLink Complete\nAccount Management\nManaging Profiles\nToken Stock and ALMS Billing\nMore\nFAQ\nProduct page\nThe Source\nALMS EULA\nGDPR FAQ\nSearching...\nMatching results\nHow to retrieve device data in a dataset?\nAirVantage allows you to retrieve firmware data from your AirLink gateways.\nFollow this tutorial to learn how to create datasets to retrieve the firmware parameters from your gateways, and how to use the scheduling functionality to automate the operation.\nTo watch the video version, click on the screen above.\nOr, if you prefer, follow the steps below at your own pace.\n1 /\nCreate\n2 /\nretrieve\n3 /\nUse\nStep 1: Create Dataset\nIn AirVantage terminology, a \u201CDataset\u201D is a list of ALEOS parameters that a user would like retrieved from their gateways. For systems with the heartbeat configured when communicating to AirVantage for the first time, the device will be associated to a default status report. It includes information such as RSSI, GPS latitude, longitude, IP address and other common information. To access additional data from your gateways, you must create a dataset that contains the specific parameters you want retrieved.\nCreate a new dataset\nLet\u2019s start by creating a new dataset. Datasets are managed from the Configure screen under the Datasets tab.\nFrom here, you can see all of the datasets available and you have the ability to modify them. To create a new dataset, just click on the \u201Cplus\u201D icon.\nBecause datasets are bringing back specific ALEOS parameters, we need to first select the firmware version we want this dataset associated with.  We\u2019ll select the ALEOS firmware of our GX400 gateway.\nSearch your parameters\nBased on the firmware version selected, you are now presented with the ALEOS parameters available.  From here, you can browse and select the parameters you wish to make part of the dataset.\nTo find a parameter to be included in your dataset, you can either enter its name in the search field, or browse through the hierarchy\nFor example, let\u2019s use the search field to find the Serial Port status parameters.\nSelect your parameters\nAs you type, the list of parameters is refined, and you are presented with the matches in green.\nSelect the parameter to include in the dataset. A counter at the bottom of the screen is automatically incremented. It indicates the number of parameters you\u2019ve added to the dataset. A red \u201Cx\u201D also allows you to unselect all of them.\nAlternatively, back at the configuration root page, you can also browse through the hierarchy to get to the same parameters.\nSave your dataset\nChoose the parameter selection method that best suits your dataset requirements.\nWhen you are happy with your dataset, click on Save, name your dataset and optionally describe it.\nA message block indicates that the dataset has been successfully created.\nYou can now use your dataset in 2 ways. You can request the dataset as needed or you can schedule it.\nStep 2: Retrieve Dataset\nTo manually retrieve the dataset from a device, let\u2019s find our target device in the list of systems.\nSelect the dataset to use\nOpen the\nMonitor > Systems\nlist, find your system in the list and check it.\nThen select the\nRetrieve > Device data\ncommand from the\nMore\nbutton on the Action Menu, also available on the system\u2019s Monitor page.\nYou can find the dataset just created in the list.\nRequest a dataset\nEither ask for it at the next connection or set a specific schedule for it.\nA message box confirms that an operation to retrieve your data has been initiated.\nYou can track the progress of the dataset in the Latest Operations list on the system details page.\nSchedule a dataset\nAlternatively, you can schedule datasets to be retrieved repeatedly. This feature is available from the Configure Communication panel.\nNote the Advanced option, which allows you to pick the dataset as well how frequently you want it retrieved.\nNow your dataset has been requested, you can see it in the recent operations list for your system:\nStep 3: Use your Data\nView your dataset\nOnce the dataset has been retrieved, the data will be available on the Timeline page. The Timeline lists all your system communications with AirVantage over a 3-month period.\nTo view your dataset, identify the most recent communication in your timeline, click on it, and the dataset data will be displayed.\nDisplay your data\nApart from the Timeline, you can also use the Data History screen to analyze the dataset data.\nFrom the Data History page, you can use the Add chart button to define graphical charts that allow you to review the dataset data retrieved during specific time periods.\nFor instance, we want to review the ALEOS parameters: Bytes Sent and Bytes Received. Each of these data items will form a series in the chart.\nClick on Add Chart to start, then select the Custom Chart (or Traffic) tab.\nFor each series, select the source data item, and the mathematical function to apply to it. In this case, we want to know the \u201Cmean\u201D value of these parameters.\nClick on Add chart.\nYou can add multiple charts to the Data History page, to present a multi-dimensional view of the system.\nSeveral charts are provided \u201Cout of the box\u201D, including Signal Strength and LTE Signals, and Traffic.\nOnce you have added your chart(s) to the page, you can select the time period to display, such as hourly, daily or monthly, to get the level of detail you need."})]})}function h(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>s});var n=a(6540);let o={},r=n.createContext(o);function i(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);